#include <bits/stdc++.h>
using namespace std;

void read_value(int &x) {
    x = 0; bool neg = false; char c;
    do {
        c = getchar();
        if (c == '-') neg = true;
    } while (!isdigit(c));
    while (isdigit(c)) {
        x = x * 10 + (c - '0');
        c = getchar();
    }
    if (neg) x = -x;
}

void read_value_ll(long long &x) {
    x = 0; bool neg = false; char c;
    do {
        c = getchar();
        if (c == '-') neg = true;
    } while (!isdigit(c));
    while (isdigit(c)) {
        x = x * 10 + (c - '0');
        c = getchar();
    }
    if (neg) x = -x;
}

long long n, k, mod;
int fact[262155], invFact[262155], logArr[262155], cnt2[262155];
int dp[262155][31];
bool visited[262155][31];
vector<pair<int, int>> record;

int countDiv2(int x) {
    int c = 0;
    while (x && (x & 1) == 0) {
        ++c; x >>= 1;
    }
    return c;
}

int power(int base, long long exp) {
    int res = 1;
    while (exp > 0) {
        if (exp & 1) res = (long long)res * base % mod;
        base = (long long)base * base % mod; exp >>= 1;
    }
    return res;
}

int choose(int n, int m) {
    return (long long)fact[n] * invFact[m] % mod * invFact[n - m] % mod;
}

int solve(int n, int k) {
    if (n == 0) return 1;
    if (k == 0) return 0;
    if (dp[n][k] != -1) return dp[n][k];
    int res = 0;
    int limit = (1 << logArr[n]);
    for (int i = n; i >= limit; i -= 2) {
        res = (res + (long long)choose(n, i) * solve(n - i, k - 1) % mod * k) % mod;
    }
    return dp[n][k] = res;
}

int performBFS(int n, int k) {
    static queue<pair<int, int>> q;
    q.push({n, k});
    while (!q.empty()) {
        auto [x, y] = q.front(); q.pop();
        record.emplace_back(x, y);
        if (x == 0 || y == 0) continue;
        int limit = (1 << logArr[x]);
        for (int i = x; i >= limit; i -= 2) {
            if (cnt2[i] + cnt2[x - i] == cnt2[x] && !visited[x - i][y - 1]) {
                visited[x - i][y - 1] = true;
                q.push({x - i, y - 1});
            }
        }
    }
    for (int i = (int)record.size() - 1; i >= 0; --i) {
        int x = record[i].first, y = record[i].second;
        if (x == 0) {
            dp[x][y] = 1; continue;
        }
        if (y == 0) {
            dp[x][y] = 0; continue;
        }
        int limit = (1 << logArr[x]);
        for (int i = x; i >= limit; i -= 2) {
            if (cnt2[i] + cnt2[x - i] == cnt2[x])
                dp[x][y] = (dp[x][y] + (long long)choose(x, i) * dp[x - i][y - 1] % mod * y) % mod;
        }
    }
    return dp[n][k];
}

int main() {
    read_value(n); read_value(k); read_value_ll(mod);
    fact[0] = 1;
    memset(visited, 0, sizeof(visited));
    logArr[0] = -1;
    for (int i = 1; i <= 262150; ++i) {
        fact[i] = (long long)fact[i - 1] * i % mod;
        logArr[i] = logArr[i >> 1] + 1;
        cnt2[i] = cnt2[i - 1] + countDiv2(i);
    }
    invFact[262150] = power(fact[262150], mod - 2);
    for (int i = 262149; i > 0; --i)
        invFact[i] = (long long)invFact[i + 1] * (i + 1) % mod;
    invFact[0] = invFact[1];
    if (n & 1) {
        printf("%d\n", power(k, n));
    } else {
        int cnt = 0;
        for (int i = 0; i < 62; ++i) {
            if (n & (1LL << i)) ++cnt;
        }
        int ans = power(k, n);
        printf("%d\n", ((ans - performBFS(n, k)) % mod + mod) % mod);
    }
}
